import{_ as d,o as e,a as r,b as p}from"./app.BGziXukh.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"Device侧C++语言支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp_language_feature"},{"text":"C++17语言特性","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md","filePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md","lastUpdated":1794967785000}'),s={name:"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp17_language_feature.md"};function a(c,t,o,w,h,n){return e(),r("div",null,[...t[0]||(t[0]=[p('<div><article class="markdown-body"><h1>C++17语言特性</h1><p>Ascend C Device侧对C++17语言特性的支持情况如下表所示：</p><table><thead><tr><th>C++17特性</th><th>C++17 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>移除trigraphs</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4086.html">N4086</a></td><td>是</td><td>三字符组不再转译。</td></tr><tr><td>u8字符字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4267.html">N4267</a></td><td>是</td><td><code>u8&#39;x&#39;</code>形式可用。</td></tr><tr><td>折叠表达式</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4295.html">N4295</a></td><td>是</td><td>支持一元与二元折叠，如<code>(args + ... + 0)</code>。</td></tr><tr><td>命名空间与枚举器属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4266.html">N4266</a></td><td>是</td><td><code>namespace [[maybe_unused]] ns {...}</code>、枚举器携带属性可用。</td></tr><tr><td>嵌套命名空间定义</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4230.html">N4230</a></td><td>是</td><td><code>namespace a::b::c {...}</code>形式可用。</td></tr><tr><td>非类型模板参数的常量求值</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4268.html">N4268</a></td><td>是</td><td>非类型模板实参允许常量表达式求值，如<code>template &lt;int N&gt;</code>以<code>N/2</code>作实参。</td></tr><tr><td>扩展static_assert</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n3928.pdf">N3928</a></td><td>是</td><td>static_assert可省略消息串。</td></tr><tr><td>花括号初始化列表的auto推导新规则</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n3922.html">N3922</a></td><td>是</td><td><code>auto x{1};</code>推导为int而非initializer_list。</td></tr><tr><td>模板模板参数允许typename</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2014/n4051.html">N4051</a></td><td>是</td><td><code>template &lt;template &lt;typename&gt; typename TT&gt;</code>形式可用。</td></tr><tr><td><code>[[fallthrough]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0188r1.pdf">P0188R1</a></td><td>是</td><td>switch分支末尾标注<code>[[fallthrough]]</code>后，贯穿不产生告警。</td></tr><tr><td><code>[[nodiscard]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0189r1.pdf">P0189R1</a></td><td>是</td><td>忽略返回值会产生告警。</td></tr><tr><td><code>[[maybe_unused]]</code>属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0212r1.pdf">P0212R1</a></td><td>是</td><td>标注后未使用的变量与形参不产生告警。</td></tr><tr><td>聚合初始化扩展</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0017r1.html">P0017R1</a></td><td>是</td><td>含基类的聚合可直接花括号初始化。</td></tr><tr><td>constexpr lambda</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0170r1.pdf">P0170R1</a></td><td>是</td><td><code>constexpr auto f = [...] constexpr {...}</code>编译期调用可用</td></tr><tr><td>一元折叠与空参数包</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0036r0.pdf">P0036R0</a></td><td>是</td><td>空参数包的一元折叠仅<code>&amp;&amp;</code>、`</td></tr><tr><td>泛化基于范围的for循环</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0184r0.html">P0184R0</a></td><td>是</td><td>begin、end可返回不同类型。</td></tr><tr><td>lambda按值捕获<code>*this</code></td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0018r3.html">P0018R3</a></td><td>是</td><td><code>[*this]</code>捕获当前对象副本，SIMD与SIMT混合编程场景写法见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>enum class构造规则</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0138r2.pdf">P0138R2</a></td><td>是</td><td>整型可直接列表初始化enum class。</td></tr><tr><td>十六进制浮点字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0245r1.html">P0245R1</a></td><td>是</td><td><code>0x1.8p3</code>形式可用。</td></tr><tr><td>超对齐数据的动态内存分配</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0035r4.html">P0035R4</a></td><td>否</td><td>Device侧不支持动态内存分配。</td></tr><tr><td>保证拷贝消除</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0135r1.html">P0135R1</a></td><td>是</td><td>纯右值初始化对象时保证不产生拷贝。</td></tr><tr><td>表达式求值顺序细化</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0145r3.pdf">P0145R3</a></td><td>是</td><td>后缀表达式先于实参、运算符左操作数先于右等求值顺序规则生效，而C++11标准中的“顺序点”特性指Device侧不提供顺序点相关库设施，与本条不冲突。</td></tr><tr><td>constexpr if</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0292r2.html">P0292R2</a></td><td>是</td><td>if constexpr按条件裁剪实例化分支。</td></tr><tr><td>带初始化器的选择语句</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0305r1.html">P0305R1</a></td><td>是</td><td>支持<code>if (init; cond)</code>与<code>switch (init; cond)</code>。</td></tr><tr><td>类模板的模板实参推导</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0091r3.html">P0091R3</a></td><td>是</td><td>构造函数实参可推导类模板实参，如<code>Box b(7);</code>。</td></tr><tr><td>auto声明非类型模板参数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0127r2.html">P0127R2</a></td><td>是</td><td>支持<code>template &lt;auto V&gt;</code>形式。</td></tr><tr><td>属性命名空间免重复</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0028r4.html">P0028R4</a></td><td>是</td><td>using属性声明后可省略命名空间限定。</td></tr><tr><td>忽略不支持的非标准属性</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0283r2.html">P0283R2</a></td><td>是</td><td>未知属性仅告警不报错。</td></tr><tr><td>结构化绑定</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0217r3.html">P0217R3</a></td><td>是</td><td>支持<code>auto [a, b] = expr;</code>绑定结构体成员。</td></tr><tr><td>移除register关键字弃用用法</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0001r1.html">P0001R1</a></td><td>是</td><td>register不再是合法存储类说明符。</td></tr><tr><td>移除operator++(bool)弃用用法</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0002r1.html">P0002R1</a></td><td>是</td><td>bool不再支持自增自减。</td></tr><tr><td>异常规格成为类型系统一部分</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0012r1.html">P0012R1</a></td><td>是</td><td>noexcept参与函数类型；Device侧不支持异常抛出。</td></tr><tr><td><code>__has_include</code></td><td><a href="https://wg21.link/p0061">P0061R1</a></td><td>是</td><td><code>#if __has_include(&lt;header&gt;)</code>按头文件是否存在取值，可用于条件引入。</td></tr><tr><td>继承构造函数措辞重写</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2015/p0136r1.html">P0136R1</a></td><td>是</td><td>继承构造函数按基类构造等价实现。</td></tr><tr><td>内联变量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0386r2.pdf">P0386R2</a></td><td>是</td><td>支持<code>inline constexpr</code>变量定义。</td></tr><tr><td>模板模板实参匹配DR150</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0522r0.html">P0522R0</a></td><td>条件支持</td><td>默认编译选项下不可用，增加-frelaxed-template-template-args编译选项后可用。</td></tr><tr><td>移除动态异常规格</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0003r5.html">P0003R5</a></td><td>是</td><td>动态异常规格语法移除。</td></tr><tr><td>using声明中的包展开</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0195r2.html">P0195R2</a></td><td>是</td><td>支持<code>using Bs::operator()...;</code>包展开。</td></tr><tr><td>字节类型定义</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0298r0.pdf">P0298R0</a></td><td>是</td><td><code>std::byte</code>可用，<code>&lt;cstddef&gt;</code>可在Device侧包含。</td></tr><tr><td>类内显式实例化DR727</td><td><a href="https://cplusplus.github.io/CWG/issues/727.html">CWG727</a></td><td>是</td><td>类内显式实例化按缺陷报告决议实现。</td></tr></tbody></table></article></div>',1)])])}const i=d(s,[["render",a]]);export{l as __pageData,i as default};
